INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 7001, "2015/12/17 15:00:00", 1, 0.0, 7, "キャル", 0.0, "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 7002, "2015/12/17 15:00:00", 1, 0.0, 7, "コッコロ", 0.0, "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 7003, "2015/12/17 15:00:00", 1, 0.0, 7, "ペコリーヌ", 0.0, "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 10001, "2015/12/17 15:00:00", 1, 0.0, 10, "ペコリーヌ", 0.0, "ジュエルを食べ物…\nいえ、貴重品と交換できます！", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 10002, "2015/12/17 15:00:00", 1, 0.0, 10, "キャル", 0.0, "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 10003, "2015/12/17 15:00:00", 1, 0.0, 10, "コッコロ", 0.0, "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 10004, "2015/12/17 15:00:00", 2, 0.0, 10, "シェフィ", 0.0, "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", 0, 1, -363.0, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 12001, "2015/12/17 15:00:00", 1, 0.0, 12, "ペコリーヌ", 0.0, "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", 0, 1, -416.5, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 13001, "2015/12/17 15:00:00", 1, 0.0, 13, "キャル", 0.0, "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 13002, "2015/12/17 15:00:00", 1, 0.0, 13, "コッコロ", 0.0, "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 13003, "2015/12/17 15:00:00", 2, 0.0, 13, "シェフィ", 0.0, "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", 0, 1, -363.0, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 13004, "2015/12/17 15:00:00", 1, 0.0, 13, "ペコリーヌ", 0.0, "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 14001, "2015/12/17 15:00:00", 1, 0.0, 14, "コッコロ", 0.0, "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 14002, "2015/12/17 15:00:00", 2, 0.0, 14, "シェフィ", 0.0, "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", 0, 1, -363.0, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 14003, "2015/12/17 15:00:00", 1, 0.0, 14, "ペコリーヌ", 0.0, "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 14004, "2015/12/17 15:00:00", 1, 0.0, 14, "キャル", 0.0, "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 15001, "2015/12/17 15:00:00", 1, 0.0, 15, "コッコロ", 0.0, "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", 0, 1, -470.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 16001, "2015/12/17 15:00:00", 2, 0.0, 16, "シェフィ", 0.0, "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", 0, 1, -363.0, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 16002, "2015/12/17 15:00:00", 1, 0.0, 16, "ペコリーヌ", 0.0, "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 16003, "2015/12/17 15:00:00", 1, 0.0, 16, "キャル", 0.0, "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 16004, "2015/12/17 15:00:00", 1, 0.0, 16, "コッコロ", 0.0, "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 17002, "2015/12/17 15:00:00", 1, 0.0, 17, "コッコロ", 0.0, " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 17004, "2015/12/17 15:00:00", 1, 0.0, 25, "キャル", 0.0, "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 17005, "2015/12/17 15:00:00", 1, 0.0, 25, "コッコロ", 0.0, "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 17006, "2015/12/17 15:00:00", 2, 0.0, 25, "シェフィ", 0.0, "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", 0, 1, -363.0, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 17007, "2015/12/17 15:00:00", 1, 0.0, 25, "ペコリーヌ", 0.0, "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 18001, "2015/12/17 15:00:00", 1, 0.0, 18, "カリン", 0.0, "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", 0, 1, -363.0, 190801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 18002, "2015/12/17 15:00:00", 1, 0.0, 18, "カリン", 0.0, "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", 0, 1, -363.0, 190801, 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 19001, "2015/12/17 15:00:00", 1, 0.0, 19, "カリン", 0.0, "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", 0, 1, -470.0, 190801, 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 19002, "2015/12/17 15:00:00", 1, 0.0, 19, "カリン", 0.0, "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", 0, 1, -470.0, 190801, 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 20001, "2015/12/17 15:00:00", 1, 0.0, 20, "カリン", 0.0, "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", 0, 1, -470.0, 190801, 5);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 20002, "2015/12/17 15:00:00", 1, 0.0, 20, "カリン", 0.0, "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", 0, 1, -470.0, 190801, 6);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 21001, "2015/12/17 15:00:00", 1, 0.0, 21, "キャル", 0.0, "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 21002, "2015/12/17 15:00:00", 1, 0.0, 21, "コッコロ", 0.0, "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 21003, "2015/12/17 15:00:00", 2, 0.0, 21, "シェフィ", 0.0, "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", 0, 1, -363.0, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 21004, "2015/12/17 15:00:00", 1, 0.0, 21, "ペコリーヌ", 0.0, "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 22001, "2015/12/17 15:00:00", 1, 0.0, 22, "カリン", 0.0, "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", 0, 1, -430.0, 190801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 22002, "2015/12/17 15:00:00", 1, 0.0, 22, "カリン", 0.0, "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", 0, 1, -430.0, 190801, 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 23001, "2015/12/17 15:00:00", 1, 0.0, 23, "カリン", 0.0, "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", 0, 1, -430.0, 190801, 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 23002, "2015/12/17 15:00:00", 1, 0.0, 23, "カリン", 0.0, "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", 0, 1, -430.0, 190801, 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24001, "2019/01/31 12:00:00", 1, 8.0, 24, "エリコ（バレンタイン）", 4.08, "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", 10011, 2, -385.0, 109001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24002, "2019/01/31 12:00:00", 1, 8.0, 24, "エリコ（バレンタイン）", 5.0, "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", 10011, 2, -385.0, 109001, 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24003, "2019/01/31 12:00:00", 1, 8.0, 24, "エリコ（バレンタイン）", 10.11, "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", 10011, 2, -385.0, 109001, 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24004, "2019/01/31 12:00:00", 1, 8.0, 24, "エリコ（バレンタイン）", 4.0, "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", 10011, 2, -385.0, 109001, 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24005, "2019/01/31 12:00:00", 1, 8.0, 24, "エリコ（バレンタイン）", 6.0, "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", 10011, 2, -385.0, 109001, 5);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24006, "2019/01/31 12:00:00", 1, 0.0, 24, "エリコ（バレンタイン）", 0.0, "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", 10011, 1, 0.0, 109002, 6);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24007, "2019/01/31 12:00:00", 1, 0.0, 24, "エリコ（バレンタイン）", 0.0, "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", 10011, 1, 0.0, 109002, 7);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24008, "2019/01/31 12:00:00", 1, 0.0, 24, "エリコ（バレンタイン）", 0.0, "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", 10011, 1, 0.0, 109002, 8);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24009, "2019/01/31 12:00:00", 1, 0.0, 24, "エリコ（バレンタイン）", 0.0, "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", 10011, 1, 0.0, 109002, 9);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24010, "2019/01/31 12:00:00", 1, 0.0, 24, "エリコ（バレンタイン）", 0.0, "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", 10011, 1, 0.0, 109002, 10);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24011, "2019/01/31 12:00:00", 1, 8.0, 24, "シズル（バレンタイン）", 2.12, "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", 10011, 2, -385.0, 109101, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24012, "2019/01/31 12:00:00", 5, 8.0, 24, "シズル（バレンタイン）", 4.19, "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", 10011, 2, -385.0, 109101, 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24013, "2019/01/31 12:00:00", 2, 8.0, 24, "シズル（バレンタイン）", 2.3, "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", 10011, 4, -385.0, 109101, 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24014, "2019/01/31 12:00:00", 1, 0.0, 24, "シズル（バレンタイン）", 0.0, "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", 10011, 1, 0.0, 109102, 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24015, "2019/01/31 12:00:00", 5, 8.0, 24, "シズル（バレンタイン）", 5.23, "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", 10011, 2, -385.0, 109101, 5);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24016, "2019/01/31 12:00:00", 1, 0.0, 24, "シズル（バレンタイン）", 0.0, "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", 10011, 1, 0.0, 109102, 6);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24017, "2019/01/31 12:00:00", 1, 8.0, 24, "シズル（バレンタイン）", 5.01, "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", 10011, 2, -385.0, 109101, 7);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24018, "2019/01/31 12:00:00", 1, 0.0, 24, "シズル（バレンタイン）", 0.0, "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", 10011, 1, 0.0, 109102, 8);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24019, "2019/01/31 12:00:00", 1, 0.0, 24, "シズル（バレンタイン）", 0.0, "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", 10011, 1, 0.0, 109102, 9);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 24020, "2019/01/31 12:00:00", 1, 0.0, 24, "シズル（バレンタイン）", 0.0, "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", 10011, 1, 0.0, 109102, 10);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 26001, "2015/12/17 15:00:00", 2, 0.0, 26, "シェフィ", 0.0, "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", 0, 1, -363.0, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 26002, "2015/12/17 15:00:00", 1, 0.0, 26, "ペコリーヌ", 0.0, "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 26003, "2015/12/17 15:00:00", 1, 0.0, 26, "キャル", 0.0, "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 26004, "2015/12/17 15:00:00", 1, 0.0, 26, "コッコロ", 0.0, "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 27001, "2015/12/17 15:00:00", 2, 0.0, 27, "シェフィ", 0.0, "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", 0, 1, -363.0, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 27002, "2015/12/17 15:00:00", 1, 0.0, 27, "ペコリーヌ", 0.0, "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 27003, "2015/12/17 15:00:00", 1, 0.0, 27, "キャル", 0.0, "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 27004, "2015/12/17 15:00:00", 1, 0.0, 27, "コッコロ", 0.0, "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 28001, "2019/09/24 15:00:00", 1, 0.0, 28, "カリン", 0.0, "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", 0, 1, -363.0, 190801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 28002, "2019/09/24 15:00:00", 1, 0.0, 28, "カリン", 0.0, "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", 0, 1, -363.0, 190801, 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 29001, "2019/09/24 15:00:00", 1, 0.0, 29, "カリン", 0.0, "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", 0, 1, -409.0, 190801, 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 29002, "2019/09/24 15:00:00", 1, 0.0, 29, "カリン", 0.0, "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", 0, 1, -409.0, 190801, 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 30001, "2019/09/24 15:00:00", 1, 0.0, 30, "カリン", 0.0, "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", 0, 1, -409.0, 190801, 5);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 30002, "2019/09/24 15:00:00", 1, 0.0, 30, "カリン", 0.0, "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", 0, 1, -409.0, 190801, 6);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 31001, "2019/10/31 12:00:00", 1, 0.0, 31, "カリン", 0.0, "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", 0, 1, -409.0, 190801, 7);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 31002, "2019/10/31 12:00:00", 1, 0.0, 31, "カリン", 0.0, "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", 0, 1, -409.0, 190801, 8);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2020/01/04 4:59:59", 32001, "2019/12/20 5:00:00", 1, 0.0, 32, "カリン", 0.0, "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", 0, 1, -409.0, 190801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2020/01/04 4:59:59", 32002, "2019/12/20 5:00:00", 1, 0.0, 32, "カリン", 0.0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 0, 1, -409.0, 190801, 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2020/01/04 4:59:59", 33001, "2019/12/20 5:00:00", 1, 0.0, 33, "カリン", 0.0, "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", 0, 1, -409.0, 190801, 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2020/01/04 4:59:59", 33002, "2019/12/20 5:00:00", 1, 0.0, 33, "カリン", 0.0, "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", 0, 1, -409.0, 190801, 4);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2020/01/10 11:59:59", 34001, "2020/01/04 5:00:00", 1, 0.0, 34, "カリン", 0.0, "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", 0, 1, -409.0, 190801, 5);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2020/01/10 11:59:59", 34002, "2020/01/04 5:00:00", 1, 0.0, 34, "カリン", 0.0, "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", 0, 1, -409.0, 190801, 6);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 38001, "2015/12/17 15:00:00", 1, 0.0, 38, "ペコリーヌ", 5.3, "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", 0, 2, -458.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 38002, "2015/12/17 15:00:00", 1, 0.0, 38, "ペコリーヌ", 6.5, "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", 0, 2, -458.0, 105801, 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2020/04/08 23:59:59", 39005, "2020/04/01", 3, 9999.0, 39, "ペコリーヌ", 0.0, "", 0, 3, 9999.0, 105801, 0);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 40001, "2015/12/17 15:00:00", 1, 0.0, 40, "カリン", 0.0, "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", 0, 1, -430.0, 190801, 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 41001, "2015/12/17 15:00:00", 1, 0.0, 41, "シェフィ", 0.0, "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", 0, 1, -363.0, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 41002, "2015/12/17 15:00:00", 1, 0.0, 41, "ペコリーヌ", 0.0, "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 41003, "2015/12/17 15:00:00", 1, 0.0, 41, "キャル", 0.0, "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 41004, "2015/12/17 15:00:00", 1, 0.0, 41, "コッコロ", 0.0, "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 42001, "2015/12/17 15:00:00", 1, 0.0, 42, "コッコロ", 0.0, "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", 0, 1, -416.5, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (2104010, "2030/12/17 14:59:59", 42002, "2015/12/17 15:00:00", 1, 0.0, 42, "シェフィ", 0.0, "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", 0, 1, -416.5, 106401, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 42003, "2015/12/17 15:00:00", 1, 0.0, 42, "ペコリーヌ", 0.0, "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", 0, 1, -416.5, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 42004, "2015/12/17 15:00:00", 1, 0.0, 42, "キャル", 0.0, "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", 0, 1, -416.5, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 43001, "2015/12/17 15:00:00", 1, 0.0, 43, "ペコリーヌ", 0.0, "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", 0, 1, -363.0, 105801, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 43002, "2015/12/17 15:00:00", 1, 0.0, 43, "コッコロ", 0.0, "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", 0, 1, -363.0, 105901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 43003, "2015/12/17 15:00:00", 1, 0.0, 43, "キャル", 0.0, "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", 0, 1, -363.0, 106001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 43004, "2015/12/17 15:00:00", 1, 0.0, 44, "アメス", 0.0, "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", 0, 1, -416.5, 123001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 43005, "2015/12/17 15:00:00", 1, 0.0, 44, "アメス", 0.0, "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", 0, 1, -416.5, 123001, 2);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 43006, "2015/12/17 15:00:00", 1, 0.0, 45, "アメス", 5.79, "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", 0, 2, -416.5, 123001, 3);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 46001, "2015/12/17 15:00:00", 1, 0.0, 46, "アメス", 0.0, "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", 0, 1, -371.5, 123001, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 47001, "2015/12/17 15:00:00", 2, 0.0, 47, "シズル", 0.0, "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", 0, 2, -416.5, 104901, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 47002, "2015/12/17 15:00:00", 1, 0.0, 47, "リノ", 9.32, "ほんとーに不思議な場所ですね～\nお兄ちゃんが冒険を頑張れるよう\nおまじないをかけてあげますねっ\nフレーフレー、お・兄・ちゃんっ♪", 0, 2, -416.5, 101101, 1);
INSERT INTO `v1_faa898f12de002923e42c59f23bc73adfcc61d0d52df2ba9b430e074f2c6167a` VALUES (0, "2030/12/17 14:59:59", 48001, "2015/12/17 15:00:00", 2, 0.0, 48, "シズル", 0.0, "", 0, 2, -470.0, 104901, 0);
